package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ArtLiveExamAnuradhapuraSculptureBank3 {
    private const val T = "අනුරාධපුර යුගයේ මූර්ති හා ශිලා කැටයම්"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("අවුකන හිටි බුදු පිළිමයේ සමබරතාව පරීක්ෂා කිරීමට ජනප්‍රවාදයේ සඳහන් ජල බිංදු පරීක්ෂණයට අනුව නාසයේ සිට වැටෙන ජලය පතිත වන්නේ කොතැනටද?", "පාද දෙක අතර මැද පද්මාසනයට", "වම් උරහිසේ ඉහළ චීවර දාරයට", "දකුණු අතේ අභය මුද්‍රා අත්ලට", "ප්‍රතිමාවේ පිටුපස කළුගල් පවුරට", "අවුකන ප්‍රතිමාව සිරස් අක්ෂයට අනුව පරිපූර්ණ සමබරතාවයකින් නෙළා ඇති බව මෙයින් තහවුරු වේ."),
        q("අවුකන බුදු පිළිමයේ පාද යට නෙළා ඇති ද්විත්ව පද්මාසනය (Double Lotus Pedestal) නිමවා ඇත්තේ කුමන ආකාරයටද?", "වෙනම ගලකින් නෙළා සම්බන්ධ කර", "තනි පර්වතයේම කොටසක් ලෙස නෙළා", "ගඩොල් හා හුණු බදාමයෙන් බැඳ", "රන් ආලේපිත ලෝකඩ වාත්තුවකින්", "ප්‍රධාන ප්‍රතිමාව පර්වතයට සම්බන්ධව නෙළුවද පද්මාසනය වෙනම ගලකින් නිමවා සවි කර ඇත."),
        q("මාලිගාවිල හිටි බුදු පිළිමය අවුකන හා බුදුරුවගල පිළිමවලින් වෙනස් වන ප්‍රධාන ව්‍යුහාත්මක ලක්ෂණය කුමක්ද?", "පර්වතයෙන් වෙන් වූ පූර්ණ වටකුරු පිළිමයකි", "කඳු ගැටයක අර්ධ උන්නත කැටයමකි", "සමාධි මුද්‍රාවෙන් යුත් හිඳි පිළිමයකි", "මහනුවර යුගයේ දැවමය ප්‍රතිමාවකි", "මීටර් 11.5ක් පමණ උස මාලිගාවිල ප්‍රතිමාව ශ්‍රී ලංකාවේ විශාලතම නිදහස් හිටි හුණුගල් ප්‍රතිමාවයි."),
        q("මාලිගාවිල හිටි බුදු පිළිමය නෙළීම සඳහා අනුරාධපුර ශිල්පීන් යොදා ගත් ප්‍රධාන පාෂාණ මාධ්‍යය කුමක්ද?", "ස්ඵටික හුණුගල් (Crystalline Limestone)", "තද කළුගල් හෙවත් චානොකයිට් ගල්", "ගඩොල් හා හුණු බදාම ස්තරය", "ලෝකඩ හා රන් මිශ්‍ර ලෝහය", "මොනරාගල දිස්ත්‍රික්කයේ මාලිගාවිල ප්‍රතිමාව දැවැන්ත හුණුගල් කුට්ටියකින් නිමවා තිබේ."),
        q("වැල්ලවාය බුදුරුවගල පර්වත මූර්ති සමූහයේ මැද පිහිටි ප්‍රධාන බුදු පිළිමය දෙපස සිටින ප්‍රතිමා මොනවාද?", "මෛත්‍රේය හා අවලෝකිතේශ්වර බෝසත්වරුන්", "සැරියුත් හා මුගලන් මහරහතන් වහන්සේලා", "නාග රාජයන් හා වාමන දොරටුපාලයන්", "දුටුගැමුණු රජු හා පවුලේ සාමාජිකයන්", "මහායාන බෞද්ධ සම්ප්‍රදාය පිළිබිඹු කරමින් මැද බුදු පිළිමය දෙපස බෝධිසත්ව මණ්ඩල දෙකක් නෙළා ඇත."),
        q("බුදුරුවගල පර්වතයේ මූර්ති නිම කිරීමේදී පාෂාණයේ මතුපිට කලාත්මකව සකස් කර තිබුණේ කුමන අමතර ස්තරයකින්ද?", "හුණු බදාම හා ස්වාභාවික වර්ණක ආලේපයෙන්", "තඹ තහඩු හා රන් පත්‍ර ඇලවීමෙන්", "වීදුරු කැබලි මොසැයික් ඇතිරීමෙන්", "කළු ලාක්ෂා ඉටි ආලේප කිරීමෙන්", "ගල් මතුපිට රළු බව මකා සිනිඳු කිරීමට හුණු බදාම ගා වර්ණවත් කර තිබූ සාධක අදත් දැකිය හැකිය."),
        q("බුදුරුවගල මැද බුදු පිළිමයේ දකුණු අතින් නිරූපණය වන හස්ත මුද්‍රාව කුමක්ද?", "අභය මුද්‍රාව", "ධ්‍යාන මුද්‍රාව", "භූමිස්පර්ශ මුද්‍රාව", "විතර්ක මුද්‍රාව", "බුදුරුවගල ප්‍රධාන බුදු පිළිමයේ දකුණු අත අභය මුද්‍රාවෙන් ඉහළට ඔසවා ඇති අතර වම් අත සිවුරු පොට දරා සිටී."),
        q("තොලුවිල හිඳි බුදු පිළිමය හා අභයගිරි සමාධි බුදු පිළිමය අතර ඇති ප්‍රධාන මූර්ති සමානකම කුමක්ද?", "වීරාසන හා ධ්‍යාන මුද්‍රා ශෛලිය", "ත්‍රිභංග ඉරියව්ව හා මකර තොරණ", "පපුව හරහා බැඳගත් දෑත් ඉරියව්ව", "සිංහයා මත වැඩ සිටින ආසන ක්‍රමය", "අනුරාධපුර සම්භාව්‍ය යුගයේ ධ්‍යාන සමාපත්ති ගුණය මෙම ප්‍රතිමා දෙකෙන්ම මැනවින් ප්‍රකාශ වේ."),
        q("මිහින්තලේ කණ්ඨක චේතියේ වාහල්කඩ කැටයම් අතර බහුලව දැකිය හැකි හාස්‍යජනක හා සජීවී කලා අංගය කුමක්ද?", "වාමන රූප පෙළ (Ganas / Dwarfs)", "සඳකඩපහණේ ගවයා හා ඇතා", "මහනුවර ශෛලියේ හංස පූට්ටුව", "ශිව නටරාජ ලෝකඩ ප්‍රතිමාව", "මුල් යුගයේ වාහල්කඩ කැටයම් අතර සංගීත භාණ්ඩ වයන හා නටන විවිධ ඉරියව් සහිත වාමන රූප ඉතා විශිෂ්ටය."),
        q("අනුරාධපුර කුට්ටම් පොකුණේ ජලය ඇතුළු වන ස්ථානවල නිමවා ඇති අලංකාර ශිලා කැටයම් මොනවාද?", "මකර මුඛ සහ පුන්කලස් කැටයම්", "වරාහ මුඛ හා සිංහ හිස් කැටයම්", "හංස පූට්ටු සහ දේව රූප කැටයම්", "භේරුණ්ඩ පක්ෂි සහ ගජසිංහ කැටයම්", "මකර කටින් පොකුණට ජලය වැටෙන ආකාරයත් පඩිපෙළ දෙපස පුන්කලස් හා නාගරූපත් මනාව කැටයම් කර ඇත."),
        q("ඉසුරුමුණි කෞතුකාගාරයේ ඇති 'රාජකීය පවුල' (Royal Family Relief) කැටයම බොහෝ විද්වතුන් හඳුනා ගන්නේ කවුරුන් ලෙසද?", "දුටුගැමුණු රජු, පුත් සාලිය හා අශෝකමාලා", "මහා පරාක්‍රමබාහු හා ලීලාවතී බිසව", "කාශ්‍යප රජු හා සීගිරි අප්සරාවන්", "මිහිඳු හිමි හා දේවානම්පියතිස්ස රජු", "රාජකීය ආසනයක හිඳ සිටින රජු හා පිරිවර මෙම හුණුගල් ඵලකයේ ඉතා සංයමයෙන් නෙළා ඇත."),
        q("ඉසුරුමුණි පොකුණ අසල ගල් පර්වතයේ පහළින්ම දිය කෙළින අයුරින් කැටයම් කර ඇති සත්ව රූප මොනවාද?", "ඇතුන්ගේ හා ඇත් පැටවුන්ගේ රූප", "සිංහයන් හා කොටියන්ගේ රූප", "අශ්වයන් හා ගවයන්ගේ රූප", "හංසයන් හා මත්ස්‍යයන්ගේ රූප", "ගලේ ස්වභාවික හැඩය හා පොකුණේ ජල මට්ටම සමඟ සම්බන්ධ වන සේ ඇතුන් සිව්දෙනෙකු කැටයම් කර ඇත."),
        q("ඉසුරුමුණියේ 'මිනිසා සහ අශ්ව හිස' කැටයම කුමන ඉන්දියානු මූර්ති සම්ප්‍රදායේ ආභාසය පෙන්වන බව විචාරකයෝ පවසතිද?", "පල්ලව මූර්ති සම්ප්‍රදායේ", "මෞර්ය මූර්ති සම්ප්‍රදායේ", "ගාන්ධාර මූර්ති සම්ප්‍රදායේ", "මෝගල් මූර්ති සම්ප්‍රදායේ", "ක්‍රි.ව. 7 වන සියවසට අයත් මෙම මූර්තිය දකුණු ඉන්දීය පල්ලව ලාලිත්‍යය හා රේඛා සංයමය පෙන්වයි."),
        q("අනුරාධපුර සඳකඩපහණේ කේන්ද්‍රයේ පිහිටි අර්ධ නෙළුම් මලෙන් (Lotus) මහාචාර්ය පරණවිතාන මහතාට අනුව සංකේතවත් වන්නේ කුමක්ද?", "සියලු කෙලෙස් නැසූ නිර්වාණය", "සංසාර ගමනේ ගිනි දැල් හා තෘෂ්ණාව", "ජාති ජරා ව්‍යාධි මරණ යන දුක් සතර", "ලෞකික සැප සම්පත් හා රාජ්‍ය බලය", "සත්ව පේළි හා ලියවැල ඉක්මවා ඇතුළත පිහිටි නෙළුම් මල නිවන් සුවය හා පාරිශුද්ධත්වය දක්වයි."),
        q("අනුරාධපුර සඳකඩපහණේ පිටතම කෙළවර පිහිටි ගිනිදැල් රටාවෙන් (පලාපෙති) සංකේතවත් වන්නේ කුමක්ද?", "තෘෂ්ණාවෙන් දැවෙන සංසාර ගින්න", "පන්සිල් පද පහේ පාරිශුද්ධ බව", "රාජකීය ඔටුන්නේ රන් කැටයම්", "සතර දිසාවේ මුර දේවතාවන්", "සඳකඩපහණ පිටතින් ඇතුළට යන විට භව තෘෂ්ණාව පසුකර නිවන වෙත පියනැගීම සංකේතවත් කෙරේ."),
        q("අනුරාධපුර මුරගලක නාග රාජයාගේ හිස වටා නෙළා ඇති නාග පෙණ සංඛ්‍යාව සාමාන්‍යයෙන් කීයක් වේද?", "පෙණ හතක් (සත් පෙණ)", "පෙණ දෙකක් (ද්වි පෙණ)", "පෙණ දොළහක් (ද්වාදශ පෙණ)", "පෙණ එක් පෙණක් පමණි", "රත්නප්‍රාසාද මුරගල ඇතුළු විශිෂ්ට අනුරාධපුර නාග රාජ මුරගල්වල හිසට ඉහළින් නාග පෙණ හතක් දැක්වේ."),
        q("අනුරාධපුර මුරගලේ නාග රාජයා අත් දෙකෙන් දරා සිටින සශ්‍රීකත්වයේ සංකේත දෙක මොනවාද?", "පුන්කලස සහ මල් ඉත්ත (සමෘද්ධි ලතාව)", "ධර්ම චක්‍රය සහ සිංහ කඩුව", "වීණාව සහ රන් කෙණ්ඩිය", "ත්‍රිශූලය සහ ගිනි වළල්ල", "නාග රාජයා එක් අතකින් පිරුණු පුන්කලසක්ද අනෙක් අතින් මල් අත්තක්ද දරමින් සෞභාග්‍යය පිළිගන්වයි."),
        q("අනුරාධපුර කැටයම් කලාවේ 'වෙහෙරගල' පිළිමගෙයින් හා කන්දරෝඩෙයි ප්‍රදේශයෙන් හමු වූ කුඩා ප්‍රතිමා නිමවා ඇත්තේ කුමන මාධ්‍යයෙන්ද?", "රන් ආලේපිත ලෝකඩ මාධ්‍යයෙන්", "වීදුරු හා මැටි පල්ප මාධ්‍යයෙන්", "අමු කොස් ලී හා ලාක්ෂා මාධ්‍යයෙන්", "තෙත් හුණු බදාම මාධ්‍යයෙන්", "අනුරාධපුර යුගයේ ශ්‍රී ලාංකික ලෝකඩ වාත්තු තාක්ෂණයේ ඉහළ දියුණුව වෙහෙරගල අවලෝකිතේශ්වර පිළිමයෙන් පෙනේ."),
        q("අනුරාධපුර යුගයේ හමු වූ 'තාරා දේවි' (Gilt-Bronze Tara) විශිෂ්ට ලෝකඩ ප්‍රතිමාව දැනට තැන්පත් කර ඇති කෞතුකාගාරය කුමක්ද?", "ලන්ඩන් බ්‍රිතාන්‍ය කෞතුකාගාරය", "පැරිස් ලූවර් කෞතුකාගාරය", "රෝම වතිකානු කෞතුකාගාරය", "ටෝකියෝ ජාතික කෞතුකාගාරය", "නැගෙනහිර පළාතෙන් හමු වූ රන් ආලේපිත ලෝකඩ තාරා ප්‍රතිමාව මහායාන මූර්ති කලාවේ අග්‍රගණ්‍ය කෘතියකි."),
        q("පංකුලිය අශෝකාරාමයේ ඇති හිඳි බුදු පිළිමයේ අනුරාධපුර සමාධි පිළිමයෙන් වෙනස් වන ප්‍රධාන ලක්ෂණය කුමක්ද?", "දකුණු අත විතර්ක මුද්‍රාවෙන් එසවී තිබීම", "දෑත් දෙකම සැතපෙන ඉරියව්වෙන් තිබීම", "පිළිමය පිටුපස මකර තොරණක් පැවතීම", "පිළිමය සම්පූර්ණයෙන්ම රන් කැටයමක් වීම", "අභයගිරි සමාධි පිළිමය ධ්‍යාන මුද්‍රාවෙන් යුක්ත වුවද පංකුලිය ප්‍රතිමාවේ දකුණු අත දහම් දෙසන විතර්ක මුද්‍රාව පෙන්වයි."),
        q("අනුරාධපුර දක්ෂිණ ථූපය, අභයගිරිය හා ජේතවනාරාමය ආශ්‍රිත ගල් කැටයම්වල පුන්කලස් හා පංචනාරි ඝට වැනි මෝස්තර යොදාගත්තේ කුමන ස්ථානවලද?", "වාහල්කඩ පුවරු හා කොරවක්ගල්වල", "දාගැබේ ගර්භයේ ඉහළ ගඩොල් ස්තරවල", "පිළිමගෙයි ඇතුළත දැව පරාල මත", "උළු සෙවිලි කළ වහලයේ මුදුන් පෙළේ", "ප්‍රවේශ ද්වාර සහ වාහල්කඩ ඉදිරිපස අලංකරණයට ශිලා කැටයම් බහුලව යොදා ගැනිණි."),
        q("අනුරාධපුර රත්නප්‍රාසාදයේ මුරගල මුදුනේ ඇති මකර තොරණ යට නාග රාජයාට ඉහළින් කැටයම් කර ඇත්තේ කුමන රූපයද?", "කුඩා වාමන රූපයක් සහ විමාන හැඩයක්", "රන් කඩුවක් ගත් පොළොන්නරු සිංහයෙක්", "නටන ශිව නටරාජ ලෝකඩ ප්‍රතිමාවක්", "මහනුවර යුගයේ භේරුණ්ඩ පක්ෂියෙක්", "රත්නප්‍රාසාද මුරගල අනුරාධපුර මුරගල් විකාශනයේ උච්චතම හා සියුම්ම අවස්ථාව ලෙස සැලකේ."),
        q("අනුරාධපුර ථූපාරාම වටදාගෙයි වටා පිහිටි ශිලා කුළුණු හිස්වල (Column Capitals) නෙළා ඇති කැටයම් මොනවාද?", "සිංහ, ඇත් හා වාමන රූප කැටයම්", "මකර, ගව හා අශ්ව රූප කැටයම්", "හංස පූට්ටු සහ ලියවැල් පමණි", "රවුම් ග්‍රීක අයනික ලියකම්", "ථූපාරාමය වටා පිහිටි ශිලා ස්තම්භවල මුදුන කුඩා මූර්ති කැටයමින් අලංකාර කර තිබේ."),
        q("අනුරාධපුර අභයගිරි විහාරයෙන් හමු වූ පූජනීය සලකුණු කෙටූ සමචතුරස්‍ර ගල් පුවරුව හඳුන්වන්නේ කුමන නමින්ද?", "සිරිපතුල් ගල (Siri Pathul Gala)", "සඳකඩපහණ (Moonstone)", "කොරවක්ගල (Balustrade)", "පැන්තාලිය (Urinal Stone)", "බුදු පිළිම නිර්මාණයට පෙර බුදුන් වහන්සේ සංකේතවත් කිරීමට නෙළුම් මල් හා මංගල ලකුණු සහිත සිරිපතුල් ගල් වන්දනා කෙරිණි."),
        q("මිහින්තලේ රාජගිරි ලෙන හා අනුරාධපුර ඉසුරුමුණි කැටයම්වල දැකිය හැකි 'විවේකීව හිඳ සිටින' පුරුෂ රූපය (මිනිසා හා අශ්ව හිස) සිටින ඉරියව්ව කුමක්ද?", "මහාරාජ ලීලාසන ඉරියව්ව", "ධ්‍යාන වීරාසන ඉරියව්ව", "ත්‍රිභංග නර්තන ඉරියව්ව", "සිංහ සෙය්‍යා ඉරියව්ව", "එක් දණහිසක් නවා ඒ මත වම් අත තබාගෙන සිටින ගාම්භීර හා සැහැල්ලු ඉරියව්ව මහාරාජ ලීලාසනයයි."),
        q("අනුරාධපුර යුගයේ චූල කලා කෘති අතර 'රන්මසු උයනේ' කළුගල් බිත්තියක කොටා ඇති ප්‍රසිද්ධ රූප සටහන හඳුන්වන්නේ කෙසේද?", "සක්වළ චක්‍රය", "සඳකඩපහණ", "සිරිපතුල් ගල", "නවග්‍රහ මණ්ඩලය", "ජ්‍යාමිතික රේඛා, ජලජ සතුන් හා වෘත්තවලින් යුත් මෙම විශ්වීය කැටයම රන්මසු උයනේ දැකිය හැකිය."),
        q("අනුරාධපුර මැදිරිගිරිය වටදාගෙයි ඇතුළත වෘත්තාකාර ගල් වැටෙහි (Vedic Railing) විශේෂ කැටයම් ලක්ෂණය කුමක්ද?", "පෙත්මග වටා කුරුස රටා ගල් අල්ලා තිබීම", "මකර තොරණ් හතළිහක් පෙළට තිබීම", "නාග පෙණ සිය ගණනක් පිහිටීම", "රන් ආලේපිත ලෝකඩ පුවරු සවි කිරීම", "මැදිරිගිරිය වටදාගෙය එහි සරල රිද්මයානුකූල ගල් වැට හා කුළුණු පෙළ නිසා ඉතා අලංකාර වේ."),
        q("රස්සෙස්සර / සැස්සේරුව (Sasseruwa) හිටි බුදු පිළිමයේ අවුකන ප්‍රතිමාවට සමාන වූවත් කැපී පෙනෙන ප්‍රධාන වෙනස කුමක්ද?", "සිවුරු රැලි නොනෙළා සම්පූර්ණ නිම නොවීම", "හිඳි ඉරියව්වෙන් නෙළා තිබීම", "රතු හුණුගලින් පමණක් නිමවා තිබීම", "දෑත් පපුව මත බැඳගෙන සිටීම", "කුරුණෑගල දිස්ත්‍රික්කයේ සැස්සේරුව ප්‍රතිමාවේ ඇතැම් කොටස් අවුකන පිළිමයට වඩා ග්‍රාම්‍ය හා නිම නොවූ ස්වරූපයක් ගනී."),
        q("අනුරාධපුර යුගයේ මූර්ති ශිල්පියා තද කළුගල් කැටයම් කිරීමේදී මතුපිට සිනිඳු බව හා චීවරයේ විනිවිද පෙනෙන ගතිය මතු කළේ කුමන ශෛලියෙන්ද?", "මතුරා සහ අමරාවතී සම්ප්‍රදායන්ගේ ආභාසයෙන්", "බටහිර රෝම ග්‍රීක ටෝගා වස්ත්‍ර ශෛලියෙන්", "මහනුවර පැතලි ද්විමාන ශෛලියෙන්", "චීන මින්ග් රාජවංශ පිඟන් ශෛලියෙන්", "ගුප්ත හා අමරාවතී ආභාසය ලබා ගනිමින්ම දේශීය ශිල්පියා ඉතා සංයමයෙන් යුත් සුවිශේෂී ශ්‍රී ලාංකේය රීතියක් ගොඩනැගුවේය."),
        q("අනුරාධපුර යුගයේ 'වැසිකිළි ගල' (Urinal Stone) කැටයම් කිරීමෙන් පවා පුරාණ කලාකරුවා පෙන්වා දුන් කලා දර්ශනය කුමක්ද?", "මතුපිට මහල් මැදුරු කැටයමින් අනිත්‍යය පෙන්වීම", "සියලු ප්‍රතිමා රන්වලින් ආලේප කිරීම", "වන සතුන් පමණක් නිරූපණය කිරීම", "විශාල යුද රථ පෙළගැස්වීම", "ලෞකික මාලිගාවල සුන්දරත්වය පවා අනිත්‍ය බව සිහිගැන්වීමට තපෝවන ආරාමවල එවැනි සියුම් කැටයම් යොදා තිබුණි.")
    )
}
